'use strict'
/**
 * This module interfaces with the pigpiod fifo to create a waveform and send it to a gpio 
 * which is used to modulate a fs1000a (or similar) transmitter to send a pair of myq codes 
 * multiple times.
 */

const rpnd = require('rpnd')
const fs = require('fs')
const readline = require('node:readline')

const config = {
  txgpio: 18,
  rxgpio: 23,
  pulseWidth: 248,
  pulseAdjust: 43,
  codeGap: 100000,
  repeats: 4,
}
/**
 * myq TX
 */
var pigProc
var pigpio
const sendQueue = []
let aCmd = undefined

function initQPigs() {
  if (!pigpio) {
    try {
      fs.statSync('/dev/pigout')
    } catch (e) {
      rpnd.warn('Daemon pigpiod not running')
      return false
    }

    const pigout = readline.createInterface({
      input: fs.createReadStream('/dev/pigout')
    })

    pigpio = fs.createWriteStream('/dev/pigpio')

    const pigserr = readline.createInterface({
      input: fs.createReadStream('/dev/pigerr')
    })

    pigout.on('line', (line) => {
      rpnd.debug(line.toString())
      if (aCmd != undefined) {
        aCmd.cb && aCmd.cb(line)
        setTimeout(() => {
          aCmd = undefined
          startQPigs()
        }, aCmd.pause ?? 0)
      }
    })

    pigserr.on('line', (line) => {
      rpnd.warn('PigError: ' + line.toString())
    })


    pigout.on('close', () => {
      rpnd.debug('pigs closed')
    })

  }
}

function startQPigs() {
  if (aCmd == undefined && sendQueue.length > 0) {
    aCmd = sendQueue.shift()
    rpnd.debug(aCmd.data)
    pigpio && pigpio.write(aCmd.data + '\n')
  }
}

function qPigs(data, pause = undefined, cb = undefined) {
  sendQueue.push({ data: data, pause: pause, cb: cb })
}

function initTx(gpio = 18, repeats = 4) {
  rpnd.debug('MyqPigs: InitTx')
  config.txgpio = gpio
  config.repeats = repeats

  initQPigs()

  return true
}




function makeWaves(data) {
  let mask = '0x' + (2n ** BigInt(config.txgpio)).toString('16')

  let lastbit = 0
  let pw = 0
  let waves = []

  let pwav = (lastbit, pw) => waves.push(lastbit == 0 ? ` 0 ${mask} ${pw}` : ` ${mask} 0 ${pw}`)

  for (let bit of ('' + data + '0').split('').map(Number)) {
    if (pw > 0 && bit != lastbit) {
      pwav(lastbit, pw + (lastbit * 2 - 1) * config.pulseAdjust)
      pw = 0
    }
    lastbit = bit
    pw += config.pulseWidth
  }
  pwav(lastbit, pw)
  waves = waves.join('')
  return waves
}

function sendCodes(data) {
  if (pigpio == undefined) throw new Error('TX not initialized')
  qPigs(`MODES ${config.txgpio} w`)
  qPigs(`WRITE ${config.txgpio} 0`)
  qPigs(`WVCLR`)
  qPigs(`WVNEW`)
  qPigs('WVAG' + ' 0 0      0' + makeWaves(data[0]))
  qPigs('WVAG' + ` 0 0 ${config.codeGap}` + makeWaves(data[1]))
  qPigs(`WVCRE`)
  for (let i = 0; i < config.repeats; i += 1) {
    qPigs(`WVTX 0`, (config.codeGap / 500) - 15)
  }
  qPigs(`WRITE ${config.txgpio} 0`)
  qPigs(`MODES ${config.txgpio} r`)

  startQPigs()
  return true
}

function busy() {
  return sendQueue.length > 0
}

function cancelTx() {
  sendQueue.length = 0
  qPigs(`WRITE ${config.txgpio} 0`)
  qPigs(`MODES ${config.txgpio} r`)
  startQPigs()
}

/**
 * myq RX
 */

let pipe

function initRx(gpio, rxcb) {
  config.rxgpio = gpio

  const pulseWidth = 246
  const minPktLen = 50
  const minPW = pulseWidth / 2
  const maxPW = pulseWidth * 5 / 2
  const midPW = pulseWidth * 3 / 2

  initQPigs()

  qPigs('NO', 0, (result) => {
    pipe = result.trim()

    rpnd.debug('Create Stream on ', pipe)

    let pigpipe = fs.createReadStream(`/dev/pigpio${pipe}`)

    let lastTick = 0
    let packet = ''
    pigpipe.on('data', (data) => {
      if (data.length % 12 != 0) throw new Error('partial buffer')
      let ofs = 0
      while (ofs < data.length) {
        /*
        gpioReport
          seqno : readUInt16LE(0)
          flags : readUInt16LE(2)
          tick  : readUInt32LE(4)
          level : readUInt32LE(8)
        */
        let tick = data.readUInt32LE(ofs + 4)
        let pw = (tick - lastTick) % 0xffffffff
        lastTick = tick
        let level = ((data.readUInt32LE(ofs + 8) >> config.rxgpio) & 0x1) > 0 ? '0' : '1'
        ofs += 12
        if (pw < maxPW && pw > minPW) {
          packet += level
          if (pw > midPW) {
            packet += level
          }
        } else {
          if (packet.length > minPktLen) {
            rxcb(packet)
          }
          packet = ''
        }
      }
    })
    qPigs(`NB ${pipe} ${1 << config.rxgpio}`)
  })
  startQPigs()

  return true
}

function stop() {
  if (pigpio) {
    pigpio.write(`NC ${pipe}\n`)
  }
}


module.exports = {
  initTx,
  sendCodes,

  initRx,
  stop,
}

function unittest() {
  console.log('Unit Test')

  initTx(23)
  sendCodes(['101010101010101010101010101010100101010110101010101010100110101001010101101001010101100101010110100101101001100101011010101', '101010101010101010101010101010100101010110011010011010100110100101101010101010101010101001100110010101100101010110101010101'])

  process.stdin.on('data', function () {
    rpnd.debug('Bye')
    process.kill(process.pid, 'SIGHUP')
  })

}

if (require.main === module) {
  unittest()
}